WITH src AS (SELECT * FROM order_items WHERE order_id IN (13, 18)), order_id_summary AS (SELECT order_id, CASE WHEN quantity >= 8 THEN 'high' WHEN quantity >= 3 THEN 'mid' ELSE 'low' END AS quantity_bucket, COUNT(quantity) AS quantity_count FROM src GROUP BY order_id, CASE WHEN quantity >= 8 THEN 'high' WHEN quantity >= 3 THEN 'mid' ELSE 'low' END) SELECT * FROM order_id_summary ORDER BY quantity_bucket;
